text(await tools.exec_command({cmd:"git rev-parse HEAD && python3 - <<'PY'
from pathlib import Path
import json,hashlib
pub=Path('pact/docs/evidence'); v=json.loads((pub/'curveball-databricks-verification.json').read_text())
for row in v['records']:
 raw=(Path('pact/runs')/row['cloud_run']/'report.json').read_bytes(); original=json.loads(raw); derived=json.loads((pub/row['published_report']).read_text())
 assert hashlib.sha256(raw).hexdigest()==row['report_sha256']
 original['request']['repo_path']='.'; original['backend_metadata'].pop('artifact_folder',None)
 print(row['published_report'],'normalized copy exact:', original==derived)
 if original!=derived: print('differing keys',[k for k in original if original[k]!=derived.get(k)])
PY","workdir":"/Users/shaurya/Desktop/BTW/PACT-fork","max_output_tokens":2000}));

